// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Walk me through the life of a single limit buy order, from the trader tapping buy to the shares landing in their demat account.", "The broker OMS validates symbol, lot and tick size, order type, KYC and segment permissions. Its RMS blocks margin in the ledger, then sends the order over FIX or the native protocol. The exchange gateway authenticates the session, applies rate limits and timestamps it. Pre-trade risk checks price bands, quantity and value limits, and member limits. The sequencer assigns a sequence number and durably journals the order. The symbol's matching engine then rests or matches it by price-time priority. Execution reports flow back to the OMS, which updates state and adjusts margin. Book and trade events go out on multicast. Trades go to the clearing corporation, which nets and novates them. Funds and securities settle on T+1, and the broker ledger and the client's demat holding are updated."),
    s(5, "How would you partition the matching engine to scale, and what gets hard when an order involves more than one instrument?", "Partition by instrument. Each symbol's book has exactly one owner thread, and many symbols share a partition, each with its own sequencer and journal. Hot symbols and heavy derivative underlyings get their own partitions, and we rebalance only between sessions so that ordering never moves mid-day. Ordering is then guaranteed per partition, not globally. Multi-leg orders such as calendar spreads are the hard part. Either all legs live in the same partition, which is the usual answer for spread books on the same underlying, or you need a coordinator. Atomic matching across partitions brings in distributed locking and latency. Exchanges avoid it by co-locating related contracts and listing spreads as their own instruments."),
    s(5, "How do you make order entry idempotent so that a network retry never creates a duplicate order?", "Each order carries a client order ID that is unique per member session or trading day, such as ClOrdID in FIX. The OMS generates it before the first send and stores it with the order. The gateway or sequencer keeps a dedupe index of member plus ClOrdID. If a resend arrives, it returns the existing order's state instead of creating a new one. FIX session-level sequence numbers and the PossDup and PossResend flags handle retransmission at the transport layer. The dedupe index must be rebuilt from the journal on failover, or a retry right after a crash could double-book. Cancels and modifies reference the original order ID, so replaying them is naturally safe."),
    s(4, "Why must the sequencer make the journal write durable before the event reaches matching, rather than matching first and logging afterwards?", "If you match first and the process dies before the log write, you may already have sent an ack or fill that no recovery can reproduce. That loses an acknowledged trade, which is the one thing we must never do. Journaling first means every effect the engine produces can be rebuilt by deterministic replay of the journal. A standby replaying it reaches the identical book and the identical outputs. The cost is replication latency on the critical path, which we keep small with quorum replication across nearby nodes, kernel-bypass networking and small batches. Writing a write-ahead log before any externally visible effect is the core rule here."),
    s(4, "How should a modify request affect an order's time priority?", "The rule should be explicit and documented, because it is part of fairness. The common convention is that reducing quantity keeps the order's place in the queue. It takes no advantage from anyone behind it. Changing the price, or increasing the quantity, is treated as a new arrival: the order loses time priority and joins the back of its price level with a new sequence number. Otherwise a trader could join early with one lot and then grow the order while keeping a front-of-queue place. The engine applies a modify as an in-place update or as a cancel plus insert. Either way it is a journaled, sequenced event, so replay reaches the same queue position."),
    s(4, "Design the in-memory order book data structure for one symbol.", "Each side holds price levels in sorted order. Because prices are discrete ticks within a price band, an array indexed by tick offset gives O(1) level access. A sorted tree or skip list is the alternative when the range is wide. Each level is a FIFO doubly linked list of orders plus aggregate quantity. A hash map from order ID to node gives O(1) cancel and modify. Best bid and best ask pointers are cached. Prices are fixed-point integers, never floats. Memory is preallocated from object pools so the hot path never allocates or triggers garbage collection. Each order node holds the remaining quantity, member, client code, flags such as STP group, and its sequence number."),
    s(4, "How would you estimate capacity for this system in an interview without real exchange figures?", "State your assumptions clearly and work from peaks, not averages. Assume N instruments, a peak order-message rate R per second, and a burst factor at market open or during news. Size the gateways for that burst plus headroom, then split R across partitions by hot-symbol skew. A single matching thread handles a known rate based on its per-event cost, so the hottest symbol decides whether one thread per symbol is enough. Journal bandwidth is R times message size times the replication factor. Market data is usually several times the order rate, because each order produces book updates. Daily storage is the journal plus trades, kept for the regulatory retention period. I would validate all of it by replaying recorded peak days."),
    s(4, "How should the gateway enforce per-member rate limits without hurting fairness?", "Use a token bucket per member session, and optionally per user ID, with limits set by membership tier or the exchange's policy. It is enforced at the gateway before sequencing, so excess traffic never reaches risk or matching. Over-limit messages are rejected or throttled with a clear reason code. They are not queued indefinitely, because hidden queues create unfair latency. Limits should apply equally to members on the same tier, and cancels may get separate or more generous limits so firms can always reduce risk. Gateways are sharded per member so one noisy member cannot slow another's session. All throttling events are logged for surveillance."),
    s(3, "What is self-trade prevention, and how should the engine apply it?", "Self-trade prevention stops a buy and a sell from the same beneficial owner, or the same STP group, from trading with each other. Such trades are wash trades: they create fake volume and can be manipulative. When an incoming order would match a resting order with the same STP key, the engine applies a configured policy. It can cancel the incoming order, cancel the resting order, cancel both, or decrement both by the overlapping quantity. The check runs inside the matching loop, so it is deterministic and replayable, and it never lets the order skip ahead of other resting orders. The cancellation is reported in the execution report with a specific reason."),
    s(4, "How do price bands and circuit breakers interact with the matching engine?", "Static price bands per instrument are checked at pre-trade risk, so orders outside the band are rejected before sequencing. Dynamic bands can also be checked by the engine against the last traded price, because only it knows the current price. Market-wide circuit breakers are triggered by index moves at defined thresholds and halt trading across the market. A halt is a sequenced control event in the journal. Every partition processes it at a deterministic point, stops matching, rejects or queues new orders by rule, and often resumes through a call auction. Treating halts as journaled events keeps replay exact and makes it auditable which orders came before and after the halt."),
    s(4, "What should happen to a member's open orders when their gateway session disconnects?", "Offer cancel-on-disconnect as a session option. If the session drops, or heartbeats stop for a configured interval, the gateway generates cancel requests for all of that session's open orders, and possibly only for day orders. Those cancels go through the sequencer like any other event, so they are ordered and replayable. They are not applied by silently editing the book. The member gets cancel execution reports when they reconnect and resync. Without this feature, a broker that loses connectivity during a fast market keeps stale quotes it cannot manage. A per-member kill switch covers the case where the session is up but the member's systems have gone wrong."),
    s(4, "How does the broker RMS keep the margin ledger correct when partial fills, cancels and rejects arrive in unexpected orders or get duplicated?", "Treat execution reports as an ordered stream per order, keyed by the exchange's execution ID and per-order sequence. Apply each one idempotently and ignore duplicates by execution ID. Margin is a state machine on the order. Margin is blocked for the full order at entry. Each fill converts part of the block into a position obligation. A cancel or reject releases only the unfilled part. If a report arrives with a gap, the OMS asks the exchange for the missing ones rather than guessing. Ledger updates and order-state changes commit in one transaction. End-of-day reconciliation against exchange trade files and clearing obligations catches anything left over."),
    s(3, "How do you handle market orders safely in a thin or fast-moving book?", "A pure market order can sweep through many levels in an illiquid book and fill at absurd prices. Common protections are market protection limits, which convert the order to a limit at a set distance from the reference price. Price bands still cap execution, and some venues reject market orders in certain segments. The engine matches level by level until the order is filled or hits its protection limit. The leftover is cancelled, as with IOC, rather than resting at an unbounded price. Broker RMS must block margin against a worst-case price, for example the band limit, because the final fill price is unknown when the order is sent."),
    s(3, "Where do stop-loss orders live, and how do you order them when many trigger at once?", "Untriggered stop orders sit in a separate trigger book inside the same matching engine, sorted by trigger price and then by sequence. They are not visible in the market-data book. When a trade moves the last traded price through trigger levels, the engine collects the triggered orders and releases them into the main book. It does this in a deterministic order, typically by trigger price and then by original sequence. Triggering happens synchronously inside the matching loop, not on a timer, so replay reproduces it exactly. Cascades, where triggered orders move price and trigger more stops, are processed iteratively in that same deterministic order. Price bands limit how far a cascade can go."),
    s(4, "A market-data subscriber notices a gap in the multicast sequence. How does it recover?", "Each feed channel carries a monotonically increasing sequence number. The subscriber spots a gap when a sequence number is skipped. Exchanges usually publish A and B feeds over separate paths, so arbitrating between the two fills most single-packet losses. For small gaps, it asks the retransmit service, usually over TCP, for the missing range. For large gaps or a late start, it fetches a snapshot tagged with a sequence number. It then drops buffered incremental messages up to that number and applies the rest. Neither service ever talks to the matching engine. They read from a separately published copy of the event stream, so recovery traffic cannot slow matching."),
    s(4, "Journal replication is on the critical path. How do you keep its latency low without weakening durability?", "Replicate synchronously to a quorum of nodes in the same data centre or nearby racks. Use kernel-bypass or RDMA networking and preallocated, append-only memory-mapped or NVMe-backed logs. Durability then comes from the quorum holding the entry, not from a local fsync on every message. Small, adaptive batches amortise round trips under load while keeping single-message latency low when the system is idle. Replication to a far DR site runs asynchronously, so the speed of light does not set matching latency. The trade-off is a small RPO at the remote site. Monitor replication lag continuously, and stop accepting orders if the quorum is lost rather than running with less durability."),
    s(4, "How would you design disaster recovery to a geographically separate site?", "The primary site runs synchronous quorum replication locally. The journal streams asynchronously to the DR site, where warm engines continuously replay it. On a site failure, operations declares DR, often under regulatory procedure rather than automatically. The DR site fences the old primary by bumping the epoch and replays to the last received sequence. The exchange then reconciles with members: brokers compare their last execution reports with what DR holds, and orders past that point are treated as not received. Members reconnect to DR gateways and resync with sequence-based recovery. The regulator sets recovery-time expectations, so regular live DR drills, including trading sessions run from DR, are essential."),
    s(3, "How do you prove that the matching engine is truly deterministic?", "Feed the same journal to two builds, or to the primary and standby, and compare output streams and book-state hashes at checkpoints. Any difference is a bug. Inside the engine, ban nondeterministic inputs. Wall-clock time, randomness, hash-map iteration order, thread scheduling and floating point must not affect results unless the value came in through the journal. Replay production journals nightly against new builds. Use property-based tests for invariants such as no crossed book, quantity conservation, and FIFO order within a level. Periodic in-production hash comparison between primary and standby catches drift early, before a failover depends on it."),
    s(3, "What role do clocks and timestamps play, and do they decide priority?", "Priority comes from the sequencer's sequence number, not from wall-clock time. Clocks on different machines can never be synchronised perfectly, so using them for ordering would be unfair and hard to reproduce. Timestamps still matter for latency monitoring, audit trails and regulatory reporting. Gateways and engines sync clocks with PTP to the exchange's time source and stamp receive, sequence and match times. Those timestamps are recorded in the journal and reports, so investigators can rebuild what happened. If clock drift is detected, it raises an alert but never reorders events."),
    s(4, "How does an exchange keep access fair between members, especially those in colocation?", "Fairness has two parts: equal treatment once an order arrives, and equal access paths. Inside the system, a single sequencer per partition and strict FIFO make treatment equal. For access, colocation racks get equal-length cabling and identical network gear, so no member gets a shorter path to the gateway. Gateway load is balanced, and members cannot pay to pick a faster gateway without disclosure. Market data is sent to all colocated subscribers at the same time over multicast, with no unicast fast path. Indian regulators have looked closely at fair access to colocation and tick-by-tick data in the past, so the design must be auditable and logged end to end."),
    s(3, "How do you secure order entry so one member can never act on another member's orders?", "Each member session is authenticated with credentials or certificates on dedicated leased lines or colocation links, and TLS is used where the protocol supports it. The gateway binds every message to the authenticated member and trader ID and ignores any member field in the message itself. Cancels and modifies are authorised by checking that the target order belongs to the same member. Some venues also check the same user or dealer group. Admin actions such as kill switches and halts go through separate, strongly authenticated operator channels with dual control. Every action is journaled with the identity behind it, which gives an unchangeable audit trail."),
    s(3, "What privacy concerns exist in this workflow, and how do you handle client data?", "Client identity such as PAN, KYC details and bank accounts stays with the broker and the depository and clearing systems. The matching engine needs only an opaque client code and member ID. Public market data is anonymous: it shows price, quantity and side, never member or client. Order-level data with client codes is restricted to surveillance, clearing and regulatory reporting, with role-based access and audit logs. Data is encrypted in transit and at rest, and retention follows regulatory requirements. India's DPDP Act also applies to personal data the broker holds, so brokers must limit its use to the stated purposes and protect access to the client app."),
    s(4, "Explain novation and netting, and why they matter for the design.", "Novation means the clearing corporation becomes the buyer to every seller and the seller to every buyer. Members then face the CCP, not each other, which removes bilateral counterparty risk. Netting collapses each member's many trades into a single net funds and net securities obligation per settlement. That cuts the volume of transfers dramatically. For the design, the trade feed to clearing must be complete, exactly-once and reconcilable. Each trade needs a unique ID and both legs' member and client codes. The CCP's own risk system, with margins and default funds, depends on it, so a lost or duplicated trade becomes a direct financial error."),
    s(3, "How do settlement results flow back to brokers, and how do you reconcile them?", "The clearing corporation publishes obligation and settlement files or APIs per member: net funds payable or receivable, and securities to deliver or receive. The depository moves securities between demat accounts, and clearing banks move funds. The broker loads these into its back office and checks three sources against each other: its own trade book from execution reports, the exchange's trade file, and the CCP's obligations. Any break is investigated before client ledgers are finalised. The broker then credits client holdings and funds. In India, rules on client fund segregation and how quickly funds are returned shape how fast the broker must update and release client balances."),
    s(4, "Design a kill switch for a broker or member.", "A kill switch lets a member or the exchange immediately cancel all open orders for a scope and block new ones. The scope can be a member, a dealer, a client or an instrument. The trigger is an authenticated admin message, or an automatic breach such as a loss limit or an abnormal order rate. The gateway starts rejecting new orders for that scope at once. It also sends a sequenced mass-cancel event that each matching partition processes in order, so the result is deterministic and replayable. Confirmations come back as cancel reports. Re-enabling needs a deliberate action. Because a fast-failing algorithm can do great damage within seconds, the kill switch path must be tested regularly."),
    s(3, "How does the opening call auction differ from continuous matching?", "During the call auction, orders are collected but not matched, and an indicative equilibrium price may be published. At the end of the collection window, which may close at a randomised point to deter gaming, the engine computes the single price that maximises traded volume. Tie-breakers include minimum imbalance and closeness to a reference price. All eligible orders trade at that one price, allocated by price-time priority. Leftover orders move into the continuous book. The auction end is a sequenced control event, and any randomness comes from a journaled value, so replay gives the same result. Auctions are commonly used for price discovery at the open and when trading resumes after a halt."),
    s(3, "How do you enforce member-level position or exposure limits when instruments are spread across many partitions?", "Strict, instant limits across partitions would need cross-partition coordination on every order, which is far too slow. A common approach is to give each partition an allocation of the member's limit and rebalance it asynchronously. Another is to check against a shared risk state that is updated from fills, with slightly conservative buffers. The broker's RMS remains the main line of margin protection. Exchange limits are a safety net, so slight staleness that only ever errs on the safe side is acceptable. Market-wide open-interest limits, such as MWPL, can be enforced by a separate risk service that sends sequenced restriction events when thresholds are crossed."),
    s(3, "What happens if downstream consumers such as execution report delivery or the clearing feed slow down?", "The matching engine must never wait on them. It writes outputs to an append-only output journal or ring buffer. Each consumer has its own cursor and reads at its own pace, and slow consumers are allowed to fall behind and catch up from the log. If a broker's session is slow, its gateway queue grows. Past a threshold, that session is disconnected and resynced from the log, so the backlog does not spread. Lag per consumer is monitored, and alerts fire well before log retention could be exceeded. Input backpressure happens only at the gateway, through rate limits and rejects, never by stalling the engine."),
    s(3, "How would you safely roll out a new version of the matching engine?", "First, replay months of production journals through the new build and diff outputs and book hashes against the old build, bit for bit. Next, run it in shadow mode in production, reading the live journal while its outputs are discarded and compared. Any rule change, such as new order types or a new STP policy, is put behind a config flag. Flags are switched only at session boundaries and are recorded in the journal so replay knows which rules applied. Deploy only between sessions, never intraday. Keep the previous build ready to restore by replay. Notify members of behaviour changes and run mock trading sessions so they can test against the new version."),
    s(2, "How should iceberg (disclosed quantity) orders behave in a price-time priority book?", "An iceberg shows only a disclosed quantity while the rest stays hidden. The visible part sits at its price level with normal time priority. When it is fully filled, the engine refreshes the next disclosed tranche from the hidden reserve. That refresh gets a new time priority at the back of the level, as if it were a fresh arrival. This stops icebergs from always beating displayed orders that arrived later but were fully visible. The refresh happens inside the matching loop, so it is deterministic. Market data shows only the disclosed quantity, so the reserve is never revealed."),
  ],
  objective: [
    o(5, "A trader reduces the quantity of a resting limit order without changing its price. Under the usual convention, what happens to its time priority?", ["It keeps its place in the queue","It moves to the back of the price level","It is moved to the front of the level","The order is rejected and must be resent"], 0, "Reducing quantity does not disadvantage anyone behind the order, so priority is normally kept. Increasing quantity or changing price resets it."),
    o(5, "Which component decides the authoritative order in which events are processed within a partition?", ["The broker OMS timestamp","The gateway receive timestamp","The sequencer's sequence number","The trader's device clock"], 2, "The sequencer assigns one sequence number per partition and journals it. That number, not any clock, defines processing order and priority."),
    o(4, "An order's price is outside the instrument's static price band. Where should it be stopped?", ["In the matching engine after it rests","At exchange pre-trade risk, before sequencing","At the clearing corporation","By the market data feed handler"], 1, "Pre-trade risk rejects band violations straight back to the gateway, so the order never touches the book."),
    o(5, "A broker times out and resends an order with the same client order ID. What is the correct exchange behaviour?", ["Accept it as a new order","Reject both orders","Cancel the original and accept the resend","Recognise the duplicate and return the existing order's state"], 3, "Dedupe by member and client order ID makes entry idempotent, so retries never create duplicate orders."),
    o(4, "Why is each symbol's book owned by a single thread?", ["It gives deterministic, lock-free processing in strict sequence order","It reduces memory use by sharing books between threads","It allows the book to be stored in a relational database","It removes the need for a journal"], 0, "One owner thread processes events strictly in order with no lock contention. That makes the output deterministic and replayable."),
    o(4, "A buy limit order at 101 arrives when the best ask is a resting sell at 100. At what price does it trade?", ["101","100.5","100","It does not trade"], 2, "Trades execute at the resting order's price. The incoming aggressive order gets the price improvement."),
    o(4, "How does a market data subscriber detect that it has missed packets?", ["By TCP retransmission timers","By a gap in the feed's sequence numbers","By comparing wall-clock timestamps","By checksum errors only"], 1, "Each multicast channel carries increasing sequence numbers. A skipped number signals lost messages."),
    o(3, "A subscriber joining mid-session builds its book correctly by doing what?", ["Applying incremental updates from the current point only","Asking the matching engine for its in-memory book","Waiting until the next trading day","Loading a sequence-tagged snapshot, then applying buffered incremental updates after that sequence"], 3, "A snapshot tagged with a sequence number, followed by later incremental updates, rebuilds a consistent book without touching the engine."),
    o(4, "What is the main purpose of self-trade prevention?", ["To speed up matching","To stop orders from the same beneficial owner trading with each other","To hide order quantities","To enforce tick size"], 1, "Self-trades are wash trades that create fake volume. STP cancels or decrements the conflicting orders instead."),
    o(4, "In clearing, what does novation mean?", ["The clearing corporation becomes the counterparty to both buyer and seller","Trades are cancelled and re-entered the next day","Brokers settle bilaterally with each other","Trades are converted into derivatives"], 0, "Through novation the CCP stands between the parties, which removes bilateral counterparty risk."),
    o(3, "Under T+1 settlement, when are funds and securities for a Monday equity trade normally settled?", ["The same Monday","Wednesday","Tuesday, the next business day","The following Monday"], 2, "T+1 means settlement one business day after the trade date."),
    o(4, "What does cancel-on-disconnect protect against?", ["Duplicate client order IDs","Multicast packet loss","Price band breaches","Stale open orders left behind when a member's session drops"], 3, "It automatically cancels a session's resting orders when the connection or heartbeats fail, so the member is not exposed to orders it cannot manage."),
    o(4, "Before an event is sent to matching, the journal write is usually considered durable when what has happened?", ["A quorum of replicas has acknowledged it","The far DR site has written it","The event is in the sequencer's memory","The broker has acknowledged it"], 0, "Synchronous quorum replication nearby gives durability without the latency of waiting on a distant site."),
    o(4, "Which structure best fits a single symbol's order book for fast matching and cancels?", ["A single unsorted list of all orders","Sorted price levels, each a FIFO queue, plus an order-ID hash map","A relational table indexed by timestamp","A min-heap of all orders by quantity"], 1, "Sorted levels give fast best-price access, FIFO queues enforce time priority, and the hash map gives O(1) cancel and modify."),
    o(4, "What is the natural partition key for scaling the matching engine?", ["Broker member ID","Client PAN","Order type","Instrument or symbol"], 3, "Price-time priority is defined per instrument, so partitioning by symbol keeps each book's ordering inside one owner."),
    o(5, "In this workflow, where is margin first blocked for a client order?", ["The broker RMS, before the order leaves the broker","The exchange matching engine","The clearing corporation after the trade","The depository"], 0, "The broker RMS blocks margin or holdings in the margin ledger before sending, so no order goes out without cover."),
    o(4, "A buy order for 100 shares fills 40, then the trader cancels the rest. What should the broker RMS do with the blocked margin?", ["Release all of it","Keep all of it until settlement","Release the margin for the 60 unfilled shares only","Block more margin"], 2, "Margin for the 40 filled shares becomes a position obligation. Only the unfilled part is released."),
    o(3, "Why enforce per-member message rate limits at the gateway?", ["To encrypt traffic","To stop one member from flooding the system and hurting others","To set price-time priority","To net trades"], 1, "Rate limits protect shared capacity and fairness by rejecting excess traffic before it reaches risk or matching."),
    o(4, "To keep replay deterministic, what must the matching engine avoid?", ["Using fixed-point prices","Processing events in sequence order","Writing outputs to a log","Reading wall-clock time or random values that are not in the journal"], 3, "Any input that is not journaled, such as local time or randomness, would make replay diverge from the original run."),
    o(3, "When an iceberg order's visible tranche is fully filled and refreshed from its reserve, what priority does the new tranche get?", ["It keeps the original priority","It goes to the back of the price level","It moves to the front of the level","It moves to a better price"], 1, "A refreshed tranche is treated as a new arrival, so displayed orders are not always beaten by hidden quantity."),
    o(3, "What typically triggers a market-wide circuit breaker?", ["Index moves crossing defined percentage thresholds","A single broker's disconnect","A multicast gap","A slow clearing feed"], 0, "Market-wide circuit breakers are tied to index moves and halt trading across the market at set thresholds."),
    o(4, "What does a member kill switch do?", ["Restarts the matching engine","Deletes the member's trade history","Cancels the member's open orders in scope and blocks new ones","Pauses market data for everyone"], 2, "A kill switch removes risk quickly through sequenced mass cancels and blocks further entry until it is re-enabled."),
    o(3, "The OMS receives the same fill execution report twice. How should it avoid double-counting?", ["Apply both and fix it at end of day","Reject the order","Ask the trader","Deduplicate on the exchange execution ID and apply it only once"], 3, "Applying reports idempotently by execution ID keeps order state and margin correct even when reports are redelivered."),
    o(4, "How do you ensure each trade reaches the clearing corporation exactly once?", ["Send it over UDP once","Use unique trade IDs with dedupe and reconciliation against the journal","Send it only at end of day by email","Have brokers report trades instead"], 1, "At-least-once delivery plus idempotent trade IDs and reconciliation gives an effectively exactly-once trade feed."),
    o(3, "Why take periodic snapshots of matching engine state if the journal is the source of truth?", ["To shorten recovery by replaying only events after the snapshot","To replace the journal","To publish to market data subscribers","To change price-time priority"], 0, "Snapshots bound replay time. The journal stays authoritative for events after each snapshot."),
    o(4, "When a standby engine is promoted, what prevents the old primary from also emitting outputs?", ["Bigger rate limits","Faster clocks","Fencing with an epoch or term number that rejects the old primary's writes","Restarting all brokers"], 2, "Epoch fencing rejects journal and output writes from a stale leader, which avoids split brain."),
    o(3, "In an opening call auction, how is the single execution price usually chosen?", ["The first order's price","The average of all bids","The previous day's close, always","The price that maximises traded volume, with defined tie-breakers"], 3, "Auctions pick the equilibrium price that matches the most quantity, and use tie-breakers such as minimum imbalance."),
    o(3, "What does a public market data feed normally include about each order or trade?", ["The client's PAN","Price, quantity and side, without member or client identity","The broker's margin balance","The trader's IP address"], 1, "Public feeds are anonymous. Identities are kept for surveillance, clearing and regulators."),
    o(3, "Why are prices stored as fixed-point integers in the engine?", ["To avoid floating-point rounding errors and keep comparisons exact and deterministic","To save network bandwidth only","Because FIX requires integers","To hide prices from subscribers"], 0, "Floating-point rounding can break exact price comparisons and replay determinism. Integer ticks avoid both problems."),
    o(3, "Remote DR replication is asynchronous. What trade-off does this accept?", ["Slower local matching","Loss of price-time priority","A small possible data loss window (RPO) at the DR site","Unbounded broker rate limits"], 2, "Async replication keeps long-distance latency off the critical path, but the DR site may lag slightly behind the primary."),
  ],
};
export default bank;
